activities.codeSnippet:
class UserProfile {
    String username;
    String role;
    boolean isActive;

    // Constructor establishes valid starting security state
    UserProfile() {
        username = "guest_user";
        role = "VIEWER";
        isActive = true;
        System.out.println("🛡️ Security context established for new profile.");
    }
}

public class Main {
    public static void main(String[] args) {
        // Invoking constructor
        UserProfile user = new UserProfile();
        System.out.println("User: " + user.username + " | Role: " + user.role);
    }
}

