// What happens in memory line-by-line:
class Device {
    int batteryPercent;

    Device() {
        // Step 3: By the time we enter here, batteryPercent is already 0 in RAM
        batteryPercent = 100; // We overwrite it with full charge
        System.out.println("Battery charged to 100% at startup.");
    }
}

public class Main {
    public static void main(String[] args) {
        // 1. 'new' requests 4 bytes on heap -> batteryPercent = 0
        // 2. Javac calls Device() -> batteryPercent = 100
        // 3. Address stored in d
        Device d = new Device();
    }
}

